/**
 * AUTO-GENERATED automation — created by the spell-automation-generate skill
 * from spell-automation-proposals.md (2026-07-06).
 * Proposal feasibility: ready.
 * Degraded parts (manual): hit/miss gating of the bonus radiant dice (no
 *   attack-result event — the bonus rides the weapon's damage roll, made only on
 *   a hit); the PHB'14 version (concentration + advantage on next turn's first
 *   attack) is intentionally not automated.
 *
 * Review before trusting. Regenerating this spell OVERWRITES this file.
 * To adopt as manually maintained: remove this banner and the `autogenerated`
 * flag in the definition below — regeneration will then refuse to touch it.
 */

import {MODULE_ID} from '../../framework/constants.js';
import {inPlayActor} from '../../framework/utils.js';

/**
 * True Strike (PHB'24 cantrip) — cast through a weapon you are holding. On cast
 * the player picks one of their weapons (Booming/Green-Flame Blade pattern); the
 * automation makes that weapon's own attack, but substitutes the caster's
 * spellcasting ability for Strength/Dexterity on BOTH the attack and the damage.
 * From 5th level the strike deals extra radiant damage (1d6 at 5th, 2d6 at 11th,
 * 3d6 at 17th), and the player may choose to deal the weapon's normal damage as
 * radiant instead of its usual type.
 *
 * What is automated:
 *   - Vanilla cast noise suppressed: imported items carry a measured template
 *     and an enchant activity ("drop an item to enchant" tray on the chat card)
 *     — both are redundant next to the weapon picker, so the configure handler
 *     turns them off while the automation is enabled (disable it to get the
 *     vanilla behavior back).
 *   - Weapon choice at cast time, then triggering that weapon's attack activity.
 *   - Attack-roll ability swap: the weapon's attack activity is temporarily set
 *     to the caster's spellcasting ability, then restored after the roll (this is
 *     a write to the caster's OWN item — no GM/socket).
 *   - Damage-roll ability swap: the difference between the spellcasting modifier
 *     and the weapon's own ability modifier is folded into the damage roll at
 *     configure time, so the rolled damage uses the spellcasting ability.
 *   - Damage-type choice: the weapon's base damage part is given BOTH its own
 *     type and radiant, so dnd5e's damage roll dialog shows its native type
 *     selector — no custom menu, and picking radiant genuinely converts the
 *     weapon's own dice.
 *   - Scaling radiant dice (1d6/2d6/3d6 at 5th/11th/17th) join the damage roll
 *     as their own radiant part, crit-doubled natively.
 *
 * What is NOT automated (never blocks the cast):
 *   - No event reports hit/miss, so the bonus radiant dice ride the weapon's
 *     damage roll (rolled only on a hit in vanilla play) — ignore them on a miss.
 *   - The PHB'14 version (concentration, advantage on next turn's first attack)
 *     is intentionally left un-automated — it needs a not-yet-existing next-turn
 *     attack event and is a famously low-value spell.
 *
 * Per-item settings (Manage Automations on the spell):
 *   - weaponFilter: how the picker orders weapons (all are always listed —
 *     'equipped' puts equipped ones first, never hides the rest).
 *   - defaultWeapon: name of a weapon to always strike with, skipping the picker
 *     (filled by the picker's "don't ask again" checkbox, clearable by hand).
 */

// How long after a cast we still associate a weapon's damage roll with this
// cast, in milliseconds. Covers the normal attack -> damage-click gap.
const PENDING_WINDOW_MS = 60_000;

/** Number of d6s of bonus radiant damage for a caster level (0 below 5th). */
function radiantDice(characterLevel) {
    if (characterLevel >= 17) return 3;
    if (characterLevel >= 11) return 2;
    if (characterLevel >= 5) return 1;
    return 0;
}

/** Best-effort character level for cantrip scaling. */
function casterLevel(actor) {
    const level = actor?.system?.details?.level;
    if (typeof level === 'number' && level > 0) return level;
    const classes = actor?.classes;
    if (classes) {
        const summed = Object.values(classes).reduce((sum, c) => sum + (c.system?.levels ?? 0), 0);
        if (summed > 0) return summed;
    }
    return 1;
}

/** The caster's spellcasting ability key (falls back to the spell's, then int). */
function spellcastingAbility(actor, item) {
    return item?.system?.ability
        || item?.abilityMod
        || actor?.system?.attributes?.spellcasting
        || 'int';
}

/** Modifier for an ability key on the actor, or 0 if unreadable. */
function abilityMod(actor, ability) {
    return Number(actor?.system?.abilities?.[ability]?.mod) || 0;
}

/** The weapon's primary damage type, used to describe/tag the strike. */
function weaponDamageType(weapon) {
    const base = weapon?.system?.damage?.base;
    const types = base?.types;
    if (types?.size) return [...types][0];
    if (Array.isArray(types) && types.length) return types[0];
    return base?.type ?? 'bludgeoning';
}

/** The weapon attack activity, whichever collection shape dnd5e exposes. */
function weaponAttack(weapon) {
    return weapon?.system?.activities?.find?.(a => a.type === 'attack')
        ?? weapon?.system?.activities?.contents?.find?.(a => a.type === 'attack')
        ?? null;
}

/**
 * Candidate weapons the player may strike with. Never hides any — players
 * routinely don't maintain the equipped state in their inventory, so the
 * 'equipped' filter only ORDERS the list (equipped first, the likely picks).
 */
function pickableWeapons(actor, filter) {
    const weapons = actor.items.filter(item => item.type === 'weapon');
    if (filter === 'equipped') {
        weapons.sort((a, b) => (b.system?.equipped ? 1 : 0) - (a.system?.equipped ? 1 : 0));
    }
    return weapons;
}

/**
 * Cast configure (synchronous, before the usage dialog and any placement):
 * imported PHB'24 True Strike items resolve as an enchant activity — vanilla
 * places a measured template and puts a "drop an item to enchant" tray on the
 * chat card. The automation drives the chosen weapon's own attack instead, so
 * both are redundant: suppress the template (and its dialog checkbox) and clear
 * the enchantment profile (the tray only renders when the message carries one;
 * the profile picker in the dialog is hidden too).
 */
function configureCast(context) {
    // No enchantment profile on the message -> dnd5e never renders the enchant
    // tray; the automation's weapon picker replaces that choice.
    if (context.usageConfig.enchantmentProfile) context.usageConfig.enchantmentProfile = null;
    foundry.utils.setProperty(context.dialogConfig, 'options.display.create.enchantment', false);

    // The cast resolves as a weapon attack, not an area — turn the imported
    // template off and hide the "Place Template" checkbox in the dialog.
    if (context.usageConfig.create === false) return;
    context.usageConfig.create ??= {};
    context.usageConfig.create.measuredTemplate = false;
    foundry.utils.setProperty(context.dialogConfig, 'options.display.create.measuredTemplate', false);
}

/**
 * Cast handler (only the acting client runs this): pick the weapon and the
 * damage-type mode, tag the weapon for its next damage card, swap the attack
 * activity's ability to the caster's spellcasting ability, trigger the attack,
 * then restore the weapon's original attack ability.
 */
async function cast(context) {
    const actor = context.actor;
    if (!actor) return;

    const spellAbility = spellcastingAbility(actor, context.item);
    const dice = radiantDice(casterLevel(actor));

    const filter = context.settings?.weaponFilter ?? 'equipped';
    // Weapons come from the IN-PLAY actor: a cast arriving on the base actor
    // (sidebar sheet, Actor.<id> hotbar macros) while the player runs an
    // unlinked token would miss weapons living on the token's delta (e.g. a
    // summoned Shadow Blade). All later writes go to the chosen weapon itself,
    // which that player owns either way.
    const weapons = pickableWeapons(inPlayActor(actor), filter);
    // Never block the cast: no held weapon to strike with, nothing to drive.
    if (!weapons.length) return;

    // A preselected weapon (the setting, filled by hand or by the picker's
    // "don't ask again" checkbox) skips the dialog entirely; if it is gone
    // (dropped/renamed), fall back to asking.
    const preset = (context.settings?.defaultWeapon ?? '').trim();
    let weapon = preset ? weapons.find(w => w.name === preset) ?? null : null;
    if (!weapon && weapons.length === 1) weapon = weapons[0];
    if (!weapon) {
        const choice = await chooseWeapon(context.item, weapons);
        weapon = choice?.weapon ?? null;
        if (weapon && choice.remember) {
            // Persist into the per-item settings so Manage Automations shows the
            // name (clear the field there to be asked again). Written to the
            // actor's canonical spell — context.item may be an ephemeral clone.
            const spell = actor.items.get(context.item.id) ?? context.item;
            await spell.setFlag(MODULE_ID, 'settings.trueStrike.defaultWeapon', weapon.name).catch(() => {});
        }
    }
    if (!weapon) return; // player cancelled the picker — the vanilla cast already happened

    // Tag the weapon so its next damage roll (within the window) gets the bonus
    // radiant dice, the ability-mod correction, and the native weapon/radiant
    // type selector in the damage dialog. Stored on the caster's own weapon — no
    // cross-client writes.
    await weapon.setFlag(MODULE_ID, 'trueStrike', {
        dice,
        spellAbility,
        weaponType: weaponDamageType(weapon),
        at: Date.now()
    });

    // Attack-roll ability swap: temporarily point the weapon's attack activity at
    // the spellcasting ability, roll the attack, then restore. We cannot fabricate
    // an attack roll, so we drive the weapon's own activity (the spell as written).
    const attack = weaponAttack(weapon);
    if (attack?.use) {
        const originalAbility = attack.attack?.ability ?? '';
        const needsSwap = originalAbility !== spellAbility;
        try {
            if (needsSwap) await attack.update({'attack.ability': spellAbility});
            await attack.use();
        } catch (err) {
            console.error(`${MODULE_ID} | trueStrike: failed to use weapon attack`, err);
        } finally {
            // Restore the weapon's original attack ability so True Strike doesn't
            // permanently rewrite the weapon.
            if (needsSwap) {
                await weaponAttack(weapon)?.update?.({'attack.ability': originalAbility})
                    .catch(() => {});
            }
        }
    } else {
        // No attack activity to drive; the weapon's next damage roll is still
        // adjusted via the flag set above.
        console.warn(`${MODULE_ID} | trueStrike: "${weapon.name}" has no attack activity to roll`);
    }
}

/**
 * Weapon picker dialog — a dropdown, so an arsenal of any size fits (button rows
 * capped the list). Returns {weapon, remember} or null on cancel; remember is the
 * "don't ask again" checkbox, persisted by the caller into the per-item settings.
 */
async function chooseWeapon(spell, weapons) {
    const options = weapons.map((weapon, index) => {
        const suffix = weapon.system?.equipped ? '' : ' (not equipped)';
        return `<option value="${weapon.id}"${index === 0 ? ' selected' : ''}>${weapon.name}${suffix}</option>`;
    }).join('');
    const result = await foundry.applications.api.DialogV2.wait({
        window: {title: `${spell.name}: choose a weapon`},
        content: '<p>Which weapon are you striking with?</p>'
            + `<select name="weapon" autofocus style="width: 100%">${options}</select>`
            + '<label style="display: flex; gap: 6px; align-items: center; margin-top: 8px;">'
            + '<input type="checkbox" name="remember"> Always use this weapon (don\'t ask again)</label>',
        buttons: [
            {
                action: 'strike',
                label: 'Strike',
                default: true,
                callback: (event, button) => ({
                    id: button.form?.elements.weapon?.value ?? null,
                    remember: button.form?.elements.remember?.checked ?? false
                })
            },
            {action: 'cancel', label: 'Cancel', icon: 'fa-solid fa-xmark'}
        ],
        rejectClose: false
    });
    if (!result || result === 'cancel' || !result.id) return null;
    const weapon = weapons.find(w => w.id === result.id) ?? null;
    return weapon ? {weapon, remember: result.remember} : null;
}

/**
 * Damage-roll configure (synchronous, on the rolling client, routed by actor
 * scope): if the weapon rolling damage was tagged by a recent True Strike cast,
 * rewrite the roll BEFORE the dialog and evaluation —
 *   - the base part offers radiant alongside the weapon's own damage type, so
 *     the damage dialog shows dnd5e's NATIVE type selector (no custom menu, and
 *     picking radiant genuinely converts the weapon's own dice);
 *   - the spellcasting-vs-weapon ability-mod difference is folded into the base
 *     part, so the rolled damage uses the spellcasting ability;
 *   - the scaling radiant dice join as their own part — shown in the dialog,
 *     rolled and animated once, and crit-doubled natively.
 */
function configureStrike(context) {
    const weapon = context.item;
    const pending = weapon?.getFlag?.(MODULE_ID, 'trueStrike');
    if (!pending) return;
    if (Date.now() - (pending.at ?? 0) > PENDING_WINDOW_MS) return;
    const rolls = context.config?.rolls;
    if (!rolls?.length) return;

    const first = rolls[0];
    first.options ??= {};
    const types = new Set(first.options.types ?? []);
    if (first.options.type) types.add(first.options.type);
    types.add(pending.weaponType);
    types.add('radiant');
    first.options.types = [...types];

    const delta = abilityMod(context.actor, pending.spellAbility) - weaponAbilityMod(weapon, context.actor);
    if (delta !== 0) {
        first.parts ??= [];
        first.parts.push(String(delta));
    }

    if (pending.dice > 0) {
        rolls.push({
            data: first.data ?? {},
            parts: [`${pending.dice}d6`],
            options: {type: 'radiant', types: ['radiant']}
        });
    }
}

/**
 * Damage-card handler (only the rolling client runs this): the strike's dice were
 * already rewritten at configure time — this only consumes the weapon's tag so
 * later, unrelated damage rolls go untouched.
 */
async function applyStrike(context) {
    const weapon = context.item;
    if (!weapon?.getFlag?.(MODULE_ID, 'trueStrike')) return;
    await weapon.unsetFlag(MODULE_ID, 'trueStrike').catch(() => {});
}

/** The modifier the weapon's damage actually used (best-effort). */
function weaponAbilityMod(weapon, actor) {
    const attack = weaponAttack(weapon);
    let ability = attack?.attack?.ability || attack?.damage?.ability || '';
    // Empty ability = dnd5e default. Finesse/ranged pick the best of STR/DEX;
    // otherwise melee uses STR. Approximate the same way.
    if (!ability) {
        const props = weapon?.system?.properties;
        const isFinesse = props?.has?.('fin') ?? (Array.isArray(props) && props.includes('fin'));
        const isRanged = (weapon?.system?.type?.value ?? '').toLowerCase().includes('r');
        if (isFinesse || isRanged) {
            const str = abilityMod(actor, 'str');
            const dex = abilityMod(actor, 'dex');
            return Math.max(str, dex);
        }
        ability = 'str';
    }
    return abilityMod(actor, ability);
}

export const trueStrike = {
    id: 'trueStrike',
    name: 'True Strike',
    version: '1.5.1',
    autogenerated: true,
    description: 'Suppresses the imported item\'s vanilla cast prompts (measured template placement and the "drop an item to enchant" tray) — disable the automation to get them back. On cast, prompts for one of the caster\'s weapons (a preselected weapon — the setting or the picker\'s "don\'t ask again" checkbox — skips the prompt), then makes that weapon\'s attack using the caster\'s spellcasting ability for attack and damage (the weapon\'s attack ability is swapped for the roll and restored after). The damage roll is rewritten before its dialog: the spellcasting-vs-weapon ability-mod difference is folded in, the scaling radiant dice (1d6/2d6/3d6 at 5th/11th/17th) join as their own crit-doubling part, and the base part offers both the weapon\'s type and radiant — so dnd5e\'s native type selector in the damage dialog replaces any custom menu and genuinely converts the weapon\'s dice. Reflects the PHB\'24 version. No hit/miss event exists, so the bonus rides the weapon\'s damage roll — ignore it on a miss. The PHB\'14 version (concentration, next-turn advantage) is intentionally not automated.',
    settings: [
        {
            key: 'weaponFilter',
            name: 'Weapon order',
            hint: 'How the picker orders weapons. Every weapon is always listed; "Equipped first" puts equipped ones at the top.',
            type: 'select',
            default: 'equipped',
            choices: {
                equipped: 'Equipped weapons first',
                all: 'Inventory order'
            }
        },
        {
            key: 'defaultWeapon',
            name: 'Preselected weapon',
            hint: 'Exact name of the weapon to always strike with — the picker is skipped while this is set. Filled by the picker\'s "don\'t ask again" checkbox; clear it to be asked again. If no weapon by this name is found, the picker opens.',
            type: 'text',
            default: ''
        }
    ],
    match: {
        itemNames: ['True Strike'],
        // The damage card that needs adjusting belongs to the chosen WEAPON, not
        // the spell — it can only reach applyStrike through the caster owning the
        // True Strike spell (actor scope). applyStrike self-guards on the weapon's
        // pending trueStrike flag, so other damage rolls fall straight through.
        actorItemNames: ['True Strike']
    },
    events: [
        // Item-lifecycle: only casting True Strike itself suppresses the vanilla
        // template/enchant prompts and opens the weapon picker. With the actor
        // scope above, an unscoped entry would run for EVERY spell the owner casts.
        {
            event: 'spellCastConfigure',
            handler: configureCast,
            priority: 50,
            scopes: ['item']
        },
        {
            event: 'spellCastComplete',
            handler: cast,
            priority: 50,
            scopes: ['item']
        },
        // Actor-routed: the tagged weapon's damage roll (flag set by cast()).
        // Configure rewrites the dice/types before the dialog; complete only
        // consumes the tag afterwards.
        {
            event: 'damageRollConfigure',
            handler: configureStrike,
            priority: 50,
            scopes: ['actor']
        },
        {
            event: 'damageRollComplete',
            handler: applyStrike,
            priority: 50,
            scopes: ['actor']
        }
    ]
};
